/**
* SpriteProperties
*/
var SpriteProperties = class extends EntityProperties {
	constructor(sprite) {
		super(sprite);
	}
	update() {
		const entity = this.entity;
		let _degree = this.degree;
		let _scale = {
			w: this.scale.w,
			h: this.scale.h
		};
		if (this._rotation == Rotation.DONT_ROTATE) _degree = 90;
		else if (this._rotation == Rotation.LEFT_RIGHT) {
			if (_degree < 0 || _degree > 180) {
				_degree = 90;
				_scale.w = -Math.abs(_scale.w);
			} else {
				_degree = 90;
				_scale.w = Math.abs(_scale.w);
			}
		}
		const _sprite = this.entity;
		const _drawable = _sprite.render.renderer._allDrawables[_sprite.drawableID];
		if (_drawable && _drawable.skin) {
			const fencedPosition = _sprite.render.renderer.getFencedPositionOfDrawable(_sprite.drawableID, [this.position.x, this.position.y]);
			this.position.x = fencedPosition[0];
			this.position.y = fencedPosition[1];
		}
		const prop = {
			skinId: entity.Costume.currentSkinId,
			position: [this.position.x, this.position.y],
			scale: [_scale.w, _scale.h],
			direction: _degree,
			visible: this.visible
		};
		this.updateDrawableProperties(prop);
	}
};
