//#region src/lib/entity/sprite/spriteSensingEdge.ts
/**
* Sprite Sensing(調べる) Edge
*/
var SpriteSensingEdge = class {
	entity;
	/**
	* @internal
	* @param entity {ISprite}
	*/
	constructor(entity) {
		this.entity = entity;
	}
	/**
	* 枠に触っていることの判定
	* @returns 
	*/
	get isTouching() {
		this.entity.render.renderer.updateDrawableScale(this.entity.drawableID, [this.entity.Properties.scale.w, this.entity.Properties.scale.h]);
		return this.isTouchingEdge().touch;
	}
	/**
	* 縦の枠に触っていることを判定する
	* @returns 
	*/
	get isTouchingVirtical() {
		this.entity.render.renderer.updateDrawableScale(this.entity.drawableID, [this.entity.Properties.scale.w, this.entity.Properties.scale.h]);
		const touch = this.isTouchingEdge();
		if (touch.touch === false) return false;
		const nearestEdge = touch.judge.nearestEdge;
		if (nearestEdge == "bottom" || nearestEdge == "top") return false;
		return true;
	}
	/**
	* 水平方向の枠に触っていることを判定する
	*/
	get isTouchingHorizontal() {
		this.entity.render.renderer.updateDrawableScale(this.entity.drawableID, [this.entity.Properties.scale.w, this.entity.Properties.scale.h]);
		const touch = this.isTouchingEdge();
		if (touch.touch === false) return false;
		const nearestEdge = touch.judge.nearestEdge;
		if (nearestEdge == "right" || nearestEdge == "left") return false;
		return true;
	}
	/**
	* スプライトがステージの枠に触っているか否かを判定する
	* @param _callback 
	*/
	isTouchingEdge() {
		const judge = this.onEdgeBounds();
		if (judge == null) return {
			touch: false,
			judge
		};
		if (judge.nearestEdge == "") return {
			touch: false,
			judge
		};
		return {
			touch: true,
			judge
		};
	}
	/**
	* スプライトが触っているステージの枠を返す
	*/
	onEdgeBounds() {
		const drawableID = this.entity.drawableID;
		const render = this.entity.render;
		const renderer = render.renderer;
		const drawable = renderer._allDrawables[drawableID];
		if (drawable == null || drawable.skin == null) return {
			"minDist": 0,
			"nearestEdge": ""
		};
		const bounds = renderer.getBounds(drawableID);
		if (!bounds) return {
			"minDist": 0,
			"nearestEdge": ""
		};
		const stageWidth = render.stageWidth;
		const stageHeight = render.stageHeight;
		const distLeft = Math.max(0, stageWidth / 2 + bounds.left);
		const distTop = Math.max(0, stageHeight / 2 - bounds.top);
		const distRight = Math.max(0, stageWidth / 2 - bounds.right);
		const distBottom = Math.max(0, stageHeight / 2 + bounds.bottom);
		let nearestEdge = "";
		let minDist = Infinity;
		if (distLeft < minDist) {
			minDist = distLeft;
			nearestEdge = "left";
		}
		if (distTop < minDist) {
			minDist = distTop;
			nearestEdge = "top";
		}
		if (distRight < minDist) {
			minDist = distRight;
			nearestEdge = "right";
		}
		if (distBottom < minDist) {
			minDist = distBottom;
			nearestEdge = "bottom";
		}
		if (minDist > 0) return {
			"minDist": 0,
			"nearestEdge": ""
		};
		return {
			"minDist": minDist,
			"nearestEdge": nearestEdge
		};
	}
};
