//#region src/lib/entity/entity/entitySensingSprite.ts
/**
* EntitySensingSprite
*/
var EntitySensingSprite = class {
	entity;
	constructor(entity) {
		this.entity = entity;
	}
	/**
	* 相手スプライトのどれかに衝突しているか否かを検知する
	* 第二パラメータがtrueのときは クローンを含めて検査する
	* @param targets 
	* @param includesClone
	* @returns 
	*/
	isTouchingTargetToTarget(targets, includesClone = false) {
		const targetIds = [];
		for (const t of targets) {
			const _s = t;
			if (_s.Properties.visible === true) {
				const targetDrawableID = _s.drawableID;
				targetIds.push(targetDrawableID);
			}
			if (includesClone === true && _s.isClone === false) for (const _clone of _s.clones) {
				const _cloneSprite = _clone;
				if (_cloneSprite.Properties.visible === true) targetIds.push(_cloneSprite.drawableID);
			}
		}
		if (targetIds.length > 0) {
			const me = this.entity;
			try {
				return me.render.renderer.isTouchingDrawables(me.drawableID, targetIds);
			} catch (e) {
				console.error(e);
			}
		}
		return false;
	}
	degreeToTarget(target) {
		const me = this.entity;
		const _target = target;
		let dx = _target.Properties.position.x - me.Properties.position.x;
		let dy = _target.Properties.position.y - me.Properties.position.y;
		let direction = 90 - MathUtil.radToDeg(Math.atan2(dy, dx));
		if (direction > 180) direction -= 360;
		return direction;
	}
	getTouchingTarget(targets) {
		const touchings = [];
		const me = this.entity;
		for (const t of targets) {
			const _t = t;
			if (me.id != _t.id) {
				if (this.isTouchingTargetToTarget([t]) === true) touchings.push(t);
			}
		}
		return touchings;
	}
};
